import requests
from collections.abc import Iterable

class FileWrapper:
    def __init__(self, data):
        self._data = data
    def __getattr__(self, name):
        return getattr(self._data, name)
    def __iter__(self):
        return iter(self._data)

def test_getattr_stream():
    data = FileWrapper(b"hello world")
    req = requests.Request('POST', 'http://httpbin.org/post', data=data)
    prep = req.prepare()
    # If it's detected as a stream, prep.body should be the data object itself, not the content
    assert prep.body is data
    print("Test passed!")

if __name__ == "__main__":
    try:
        test_getattr_stream()
    except Exception as e:
        print(f"Test failed: {e}")
        raise e
